#include <juce_audio_utils/juce_audio_utils.h>
#include <iostream>
#include <thread>
#include "../Source/PluginProcessor.h"
using namespace juce;
struct Clock:AudioPlayHead{double beat=0,bpm=120;bool running=true;Optional<PositionInfo>getPosition()const override{PositionInfo p;p.setBpm(bpm);p.setPpqPosition(beat);p.setIsPlaying(running);return p;}};
struct Event{double beat;int velocity;};
using Events=std::array<std::vector<Event>,128>;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
var transport(bool play){auto* o=new DynamicObject;o->setProperty("play",play);return var(o);}
int main(int argc,char**argv){ScopedJuceInitialiser_GUI init;try{
 check(argc==2,"fixture path");auto fixtures=JSON::parse(File(String::fromUTF8(argv[1])));check(fixtures.isArray(),"fixture array");
 double maxTickError=0;int fixtureCount=0;
 for(const auto& fixture:*fixtures.getArray())for(int block:{64,257,1024}){
  auto owned=std::make_unique<KhimairaProcessor>();auto& p=*owned;check((bool)p.update(fixture)["ok"],"native sequence rejected");Clock clock;p.setPlayHead(&clock);p.prepareToPlay(48000,block);
  const double length=(double)fixture["length"];const int64 total=(int64)std::llround(length*3*24000);Events actual,expected;
  // Retained native note values are exactly those generated by the JS engine.
  auto native=std::make_unique<khimaira::Sequence>();std::vector<khimaira::Note> notes;
  for(auto n:*fixture["notes"].getArray())notes.push_back({(double)n["beat"],(double)n["duration"],(int)n["note"],(double)n["velocity"]});
  check(native->assign(notes,length),"native assign");
  for(int i=0;i<native->noteCount;i++){auto a=notes[(size_t)i],b=native->notes[(size_t)i];check(a.beat==b.beat&&a.duration==b.duration&&a.pitch==b.pitch&&a.velocity==b.velocity,"raw note parity");}
  for(int cycle=0;cycle<3;cycle++)for(auto n:notes){expected[(size_t)n.pitch].push_back({cycle*length+n.beat,roundToInt(n.velocity*127)});expected[(size_t)n.pitch].push_back({cycle*length+n.beat+n.duration,0});}
  for(auto& list:expected)std::stable_sort(list.begin(),list.end(),[](auto a,auto b){const auto ta=std::llround(a.beat*1e9),tb=std::llround(b.beat*1e9);return ta!=tb?ta<tb:a.velocity<b.velocity;});
  auto record=[&](const MidiBuffer& midi){for(auto e:midi){auto m=e.getMessage();if(m.isNoteOnOrOff())actual[(size_t)m.getNoteNumber()].push_back({clock.beat+e.samplePosition/24000.,m.isNoteOn()?m.getVelocity():0});}};
  for(int64 frame=0;frame<total;frame+=block){const int count=(int)std::min<int64>(block,total-frame);AudioBuffer<float> audio(p.isMidiEffect()?0:2,count);MidiBuffer midi;clock.beat=frame/24000.;p.processBlock(audio,midi);record(midi);check(audio.getMagnitude(0,count)==0,"plugin emitted audio");}
  clock.beat=total/24000.;clock.running=false;AudioBuffer<float> audio(p.isMidiEffect()?0:2,block);MidiBuffer midi;p.processBlock(audio,midi);record(midi);
  for(int pitch=0;pitch<128;pitch++){
   check(actual[pitch].size()==expected[pitch].size(),"event count / paired note-off");
   std::array<std::vector<std::pair<int,int>>,3> cycles;
   for(size_t i=0;i<expected[pitch].size();i++){
    auto a=actual[pitch][i],e=expected[pitch][i];double error=std::abs(a.beat-e.beat)*480;maxTickError=std::max(maxTickError,error);
    check(error<=1,"more than one tick timing error");if(a.velocity!=e.velocity){std::cerr<<fixture["name"].toString()<<" block="<<block<<" pitch="<<pitch<<" i="<<i<<" actual="<<a.beat<<","<<a.velocity<<" expected="<<e.beat<<","<<e.velocity<<"\n";throw std::runtime_error("velocity mismatch");}
    if(a.velocity){int cycle=std::min(2,(int)(e.beat/length));cycles[(size_t)cycle].push_back({(int)(std::llround(a.beat*24000)-std::llround(cycle*length*24000)),a.velocity});}
   }
   if(!(cycles[0]==cycles[1]&&cycles[1]==cycles[2])){std::cerr<<fixture["name"].toString()<<" block="<<block<<" pitch="<<pitch<<"\n";for(int c=0;c<3;c++){std::cerr<<"cycle "<<c<<": ";for(auto pair:cycles[c])std::cerr<<pair.first<<","<<pair.second<<" ";std::cerr<<"\n";}throw std::runtime_error("loop results differ");}
  }
  MemoryBlock saved;p.getStateInformation(saved);auto restoredOwner=std::make_unique<KhimairaProcessor>();auto& restored=*restoredOwner;restored.setStateInformation(saved.getData(),(int)saved.getSize());
  auto originalNotes=JSON::toString(fixture["notes"]),recalled=JSON::toString(restored.snapshot()["notes"]);check(originalNotes==recalled,"saved note array changed");
  ++fixtureCount;
 }
 // Native PLAY follows host tempo even while host transport is stopped.
 auto owned=std::make_unique<KhimairaProcessor>();auto& p=*owned;Clock clock;clock.running=false;p.setPlayHead(&clock);p.prepareToPlay(48000,512);AudioBuffer<float> audio(p.isMidiEffect()?0:2,512);MidiBuffer midi;
 p.transport(transport(true));double expectedBeat=0;
 for(int i=0;i<200;i++){clock.bpm=i<100?120:180;midi.clear();p.processBlock(audio,midi);check(std::abs(p.position.load()-std::fmod(expectedBeat,16))<1e-8,"preview beat/tempo mismatch");expectedBeat+=512*clock.bpm/(60.*48000);}
 double frozen=p.position.load();for(int i=0;i<100;i++)p.status();std::this_thread::sleep_for(std::chrono::milliseconds(30));check(p.position.load()==frozen,"UI drove audio clock");
 p.transport(transport(false));midi.clear();p.processBlock(audio,midi);check(!p.playing.load(),"stop");p.transport(transport(true));midi.clear();p.processBlock(audio,midi);check(p.position.load()==0,"PLAY must restart");
 // Update in the middle of a bar; the old sequence remains until the boundary.
 auto make=[](int pitch){auto* d=new DynamicObject;d->setProperty("length",8.);Array<var> notes;for(int bar=0;bar<2;bar++){auto* n=new DynamicObject;n->setProperty("beat",bar*4.);n->setProperty("duration",4.);n->setProperty("note",pitch);n->setProperty("velocity",.7);notes.add(var(n));}d->setProperty("notes",notes);return var(d);};
 auto swapOwner=std::make_unique<KhimairaProcessor>();auto& swap=*swapOwner;Clock host;swap.setPlayHead(&host);swap.prepareToPlay(48000,1024);check((bool)swap.update(make(60))["ok"],"first update");AudioBuffer<float> buffer(swap.isMidiEffect()?0:2,1024);
 host.beat=1;MidiBuffer events;swap.processBlock(buffer,events);check((bool)swap.update(make(67))["ok"],"pending update");
 host.beat=2;events.clear();swap.processBlock(buffer,events);for(auto e:events)check(!e.getMessage().isNoteOn()||e.getMessage().getNoteNumber()!=67,"early pattern swap");
 host.beat=3.98;events.clear();swap.processBlock(buffer,events);bool oldOff=false,newOn=false;for(auto e:events){auto m=e.getMessage();if(m.getNoteNumber()==60&&m.isNoteOff())oldOff=true;if(m.getNoteNumber()==67&&m.isNoteOn()){check(oldOff,"old note not released before swap");check(std::abs(host.beat+e.samplePosition/24000.-4)*480<=1,"swap not on bar boundary");newOn=true;}}check(newOn,"no new pattern at boundary");
 std::cout<<"PASS "<<fixtureCount<<" processor cases: six patterns, exact retained beat/duration/pitch/velocity, three identical 8-bar loops at 120 BPM, blocks 64/257/1024. Maximum error "<<maxTickError<<" ticks @480 PPQ. Native PLAY tempo changes, callback suspension, STOP/restart, bar-boundary update, silent audio, state recall. MIDI FX="<<p.isMidiEffect()<<"\n";
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
